{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE retail_orders_summary_retail_order_summary AS ( SELECT * FROM retail_order_summary); CREATE OR REPLACE TABLE snitchx_eligible_not_enrolled AS ( WITH Store_Map AS ( SELECT CAST(STORE_CODE AS STRING) AS store_code, STORE_NAME AS store_name FROM SNITCH_DB.MAPLEMONK.OFFLINE_STORE_DETAILED_MAPPING WHERE STORE_NAME NOT ILIKE \'%NIL%\' AND STORE_NAME NOT ILIKE \'%SNITCH-WH%\' ), MemID_to_Shopify_pre AS ( SELECT DISTINCT TRIM(ros.mem_id) AS mem_id, TRIM(REGEXP_REPLACE(ros.shopify_user_id, \',\', \'\')) AS shopify_user_id, CASE WHEN ros.vouch_time IS NOT NULL AND TRIM(vouch_time) <> \'\' THEN CASE WHEN ros.vouch_time ILIKE \'%12:% PM%\' THEN TRY_TO_TIMESTAMP(vouch_time,\'MON DD, YYYY, HH12:MI PM\') ELSE TRY_TO_TIMESTAMP(vouch_time,\'MON DD, YYYY, HH:MI AM\') END ELSE TRY_TO_TIMESTAMP(ros.transaction_date, \'MON DD, YYYY, HH12:MI AM\') END AS txn_time, FROM snitch_db.maplemonk.retail_order_summary ros WHERE ros.mem_id IS NOT NULL AND ros.mem_id <> \'NaN\' AND ros.mem_id NOT IN (\'9999999999\',\'1111111111\',\'1231231231\', \'1234567890\',\'5555555555\',\'1234567891\') AND ros.shopify_user_id IS NOT NULL UNION SELECT DISTINCT TRIM(ros.mem_id) AS mem_id, TRIM(REGEXP_REPLACE(f.customer_id, \',\', \'\')) AS shopify_user_id, f.order_timestamp AS txn_time FROM snitch_db.maplemonk.retail_order_summary ros JOIN snitch_db.maplemonk.FACT_ITEMS_SNITCH f ON RIGHT(REGEXP_REPLACE(f.phone, \'[^0-9]\', \'\'), 10) = RIGHT(REGEXP_REPLACE(ros.mem_id, \'[^0-9]\', \'\'), 10) WHERE ros.mem_id IS NOT NULL AND ros.mem_id <> \'NaN\' AND ros.mem_id NOT IN (\'9999999999\',\'1111111111\',\'1231231231\', \'1234567890\',\'5555555555\',\'1234567891\') AND f.customer_id IS NOT NULL ), MemID_to_Shopify_ranked AS ( SELECT *, ROW_NUMBER() OVER (PARTITION BY mem_id ORDER BY txn_time DESC) AS rn FROM MemID_to_Shopify_pre ), MemID_to_Shopify AS ( SELECT mem_id, shopify_user_id FROM MemID_to_Shopify_ranked WHERE rn = 1 ), Offline_Sales AS ( SELECT ros.mem_id, map.shopify_user_id, CASE WHEN ros.vouch_time IS NOT NULL AND TRIM(ros.vouch_time) <> \'\' THEN COALESCE( TRY_TO_TIMESTAMP(ros.vouch_time), TRY_TO_TIMESTAMP(ros.vouch_time, \'MON DD, YYYY, HH12:MI PM\'), TRY_TO_TIMESTAMP(ros.vouch_time, \'MON DD, YYYY, HH:MI AM\') ) ELSE TRY_TO_TIMESTAMP(ros.transaction_date, \'MON DD, YYYY, HH12:MI AM\') END AS order_ts, SUM( TRY_TO_NUMERIC(REGEXP_REPLACE(TRIM(ros.bill_value), \'[^0-9\.-]\', \'\')) - COALESCE(TRY_TO_NUMERIC(REGEXP_REPLACE(TRIM(ros.wallet_redeemed), \'[^0-9\.-]\', \'\')), 0) ) AS net_sales, SUM(TRY_TO_NUMERIC(REGEXP_REPLACE(TRIM(ros.bill_value),\'[^0-9\.-]\',\'\'))) AS gross_sales, ABS(SUM( TRY_TO_NUMERIC(REGEXP_REPLACE(TRIM(ros.bill_gross_value),\'[^0-9\.-]\',\'\')) - TRY_TO_NUMERIC(REGEXP_REPLACE(TRIM(ros.bill_value),\'[^0-9\.-]\',\'\')) )) AS discount, SUM(TRY_TO_NUMERIC(REGEXP_REPLACE(TRIM(ros.wallet_redeemed),\'[^0-9\.-]\',\'\'))) AS wallet_redeemed_amount, COUNT(DISTINCT ros.vouch_time) AS order_count, MAX(TRIM(ros.user_name)) AS user_name, \'Offline\' AS channel, MAX(TRIM(ros.store_code)) AS store_code FROM snitch_db.maplemonk.retail_order_summary ros LEFT JOIN MemID_to_Shopify map ON ros.mem_id = map.mem_id WHERE (ros.shopify_user_id IS NOT NULL OR map.shopify_user_id IS NOT NULL) GROUP BY ros.mem_id, CASE WHEN ros.vouch_time IS NOT NULL AND TRIM(ros.vouch_time) <> \'\' THEN COALESCE( TRY_TO_TIMESTAMP(ros.vouch_time), TRY_TO_TIMESTAMP(ros.vouch_time, \'MON DD, YYYY, HH12:MI PM\'), TRY_TO_TIMESTAMP(ros.vouch_time, \'MON DD, YYYY, HH:MI AM\') ) ELSE TRY_TO_TIMESTAMP(ros.transaction_date, \'MON DD, YYYY, HH12:MI AM\') END, map.shopify_user_id ), Online_Sales AS ( SELECT TRIM(CAST(customer_id AS STRING)) AS shopify_user_id, order_timestamp AS order_ts, SUM(CASE WHEN IS_REFUND = 0 AND (RTO_QUANT = 0 OR RTO_QUANT IS NULL) THEN IFNULL(gross_sales,0) ELSE 0 END) AS net_sales, SUM(IFNULL(gross_sales,0)) AS gross_sales, SUM(IFNULL(discount,0)) - SUM(IFNULL(slashed_discount,0)) AS discount, COUNT(DISTINCT REPLACE(order_name,\'#\',\'\')) AS order_count, RIGHT(REGEXP_REPLACE(TRIM(CAST(phone AS STRING)),\'[^0-9]\',\'\'),10) AS phone, MAX(TRIM(customer_name)) AS user_name, \'Online\' AS channel, NULL AS store_code FROM snitch_db.maplemonk.FACT_ITEMS_SNITCH WHERE LOWER(order_status) NOT LIKE \'%cancel%\' AND customer_id IS NOT NULL AND gross_sales <> 0 AND lower(tags) NOT LIKE \'%creator%\' AND lower(IFNULL(discount_code,\'n\')) NOT LIKE \'%eco%\' AND lower(IFNULL(discount_code,\'n\')) NOT LIKE \'%influ%\' AND tags NOT IN (\'FLITS_LOGICERP\') GROUP BY 1,2,7 ), All_Sales AS ( SELECT shopify_user_id, order_ts, net_sales AS sales, discount, order_count, gross_sales AS g_sales, user_name, channel, store_code FROM Online_Sales UNION ALL SELECT shopify_user_id, order_ts, net_sales AS sales, discount, order_count, gross_sales AS g_sales, user_name, channel, store_code FROM Offline_Sales ), Eligibility_Details AS ( SELECT shopify_user_id, order_ts, order_ts::DATE AS order_dt, channel, store_code, sales, SUM(sales) OVER ( PARTITION BY shopify_user_id ORDER BY order_ts ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) AS cumulative_spend FROM All_Sales WHERE order_ts >= CURRENT_DATE - INTERVAL \'12 months\' ), Eligibility_Date AS ( SELECT d.shopify_user_id, d.order_dt AS eligibility_date, d.channel AS eligibility_channel, d.store_code, sm.store_name FROM ( SELECT *, ROW_NUMBER() OVER (PARTITION BY shopify_user_id ORDER BY order_dt) AS rn FROM Eligibility_Details WHERE cumulative_spend >= 5000 ) d LEFT JOIN Store_Map sm ON d.store_code = sm.store_code WHERE rn = 1 ), Last_Channel AS ( SELECT shopify_user_id, channel AS last_order_channel FROM All_Sales QUALIFY ROW_NUMBER() OVER (PARTITION BY shopify_user_id ORDER BY order_ts DESC) = 1 ), Latest_Offline_Store AS ( SELECT shopify_user_id, store_code FROM ( SELECT a.shopify_user_id, a.store_code, ROW_NUMBER() OVER ( PARTITION BY a.shopify_user_id ORDER BY a.order_ts DESC ) AS rn FROM All_Sales a JOIN Eligibility_Date ed ON a.shopify_user_id = ed.shopify_user_id WHERE a.channel = \'Offline\' AND a.store_code IS NOT NULL AND a.order_ts >= ed.eligibility_date ) WHERE rn = 1 ), Phone_Map AS ( SELECT shopify_user_id, MAX(RIGHT(REGEXP_REPLACE(phone,\'[^0-9]\',\'\'),10)) AS mobile_number FROM ( SELECT TRIM(CAST(customer_id AS STRING)) AS shopify_user_id, TRIM(CAST(phone AS STRING)) AS phone FROM snitch_db.maplemonk.FACT_ITEMS_SNITCH WHERE phone IS NOT NULL UNION ALL SELECT map.shopify_user_id, TRIM(CAST(ros.mem_id AS STRING)) AS phone FROM snitch_db.maplemonk.retail_order_summary ros LEFT JOIN MemID_to_Shopify map ON ros.mem_id = map.mem_id ) p GROUP BY 1 ), Wallet AS ( SELECT TRIM(shopify_user_id) AS shopify_user_id, membership_plan, CASE WHEN membership_enrolled_date ILIKE \'__-__-____ __:__\' THEN TO_TIMESTAMP(CONCAT(TRIM(membership_enrolled_date),\':00\'), \'DD-MM-YYYY HH24:MI:SS\') ELSE TRY_TO_TIMESTAMP(TRIM(membership_enrolled_date)) END::DATE AS membership_enrolled_date FROM snitch_db.maplemonk.s3_bucket_wallet_db WHERE shopify_user_id IS NOT NULL ), Name_Map AS ( SELECT shopify_user_id, MAX(user_name) AS user_name FROM All_Sales GROUP BY 1 ), Last_Online_Channel_Metadata AS ( SELECT shopify_user_id, webshopney, city_mapped FROM ( SELECT TRIM(CAST(customer_id AS STRING)) AS shopify_user_id, webshopney, city_mapped, order_timestamp, ROW_NUMBER() OVER (PARTITION BY customer_id ORDER BY order_timestamp DESC) AS rn FROM snitch_db.maplemonk.FACT_ITEMS_SNITCH WHERE LOWER(order_status) NOT LIKE \'%cancel%\' AND customer_id IS NOT NULL AND gross_sales <> 0 AND lower(tags) NOT LIKE \'%creator%\' AND lower(IFNULL(discount_code,\'n\')) NOT LIKE \'%eco%\' AND lower(IFNULL(discount_code,\'n\')) NOT LIKE \'%influ%\' AND tags NOT IN (\'FLITS_LOGICERP\') ) ranked WHERE rn = 1 ), User_L12 AS ( SELECT shopify_user_id, SUM(CASE WHEN order_ts BETWEEN DATEADD(year,-1,CURRENT_DATE()) AND CURRENT_DATE() THEN IFNULL(sales,0) END) AS net_spend_l12, SUM(CASE WHEN order_ts BETWEEN DATEADD(year,-1,CURRENT_DATE()) AND CURRENT_DATE() THEN IFNULL(discount,0) END) AS total_discount_l12, SUM(CASE WHEN order_ts BETWEEN DATEADD(year,-1,CURRENT_DATE()) AND CURRENT_DATE() THEN IFNULL(order_count,0) END) AS order_count_l12, SUM(CASE WHEN order_ts BETWEEN DATEADD(year,-1,CURRENT_DATE()) AND CURRENT_DATE() THEN g_sales END) AS g_sales_l12, COUNT(DISTINCT CASE WHEN order_ts BETWEEN DATEADD(year,-1,CURRENT_DATE()) AND CURRENT_DATE() THEN DATE_TRUNC(\'day\',order_ts) END) AS active_days_l12, MAX(CASE WHEN order_ts BETWEEN DATEADD(year, -1, CURRENT_DATE()) AND DATEADD(day, 1, CURRENT_DATE()) THEN order_ts END) AS last_transaction_date FROM All_Sales GROUP BY 1 ) SELECT u.shopify_user_id, (\'+91\' || LPAD(RIGHT(pm.mobile_number,10),10,\'0\')) AS phone_number, w.membership_plan, w.membership_enrolled_date, ed.eligibility_date, ed.eligibility_channel, COALESCE(los.store_code, ed.store_code) AS store_code, COALESCE(sm_los.store_name, ed.store_name) AS store_name, nm.user_name, u.net_spend_l12, u.total_discount_l12, u.order_count_l12, u.g_sales_l12, u.active_days_l12, u.last_transaction_date, COALESCE(lc.last_order_channel,\'Unknown\') AS channel, locm.webshopney AS last_online_order_channel, locm.city_mapped AS last_online_order_city FROM User_L12 u LEFT JOIN Phone_Map pm ON pm.shopify_user_id = u.shopify_user_id LEFT JOIN Wallet w ON w.shopify_user_id = u.shopify_user_id LEFT JOIN Name_Map nm ON nm.shopify_user_id = u.shopify_user_id LEFT JOIN Eligibility_Date ed ON ed.shopify_user_id = u.shopify_user_id LEFT JOIN Last_Channel lc ON lc.shopify_user_id = u.shopify_user_id LEFT JOIN Latest_Offline_Store los ON los.shopify_user_id = u.shopify_user_id LEFT JOIN Store_Map sm_los ON sm_los.store_code = los.store_code LEFT JOIN Last_Online_Channel_Metadata locm ON locm.shopify_user_id = u.shopify_user_id WHERE u.net_spend_l12 > 5000 AND u.shopify_user_id IS NOT NULL ORDER BY u.net_spend_l12 DESC);",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            